  G.cyc++; if (G.cyc > 25) G.cyc = 0;
  let [x, y] = ringGet(1, G.head); plus(x, y, 0xe6 + G.cyc);
  if (G.twoP) { [x, y] = ringGet(2, G.head); plus(x, y, 0x8c + G.cyc); }
}
