    let i = G.head - G.len[p];
    if (i <= 0) i = G.head + 15000 - G.len[p];
    const [x, y] = ringGet(p, i);
    if (x !== 0) plus(x, y, 0);
    ringSet(p, i, 0, 0);
  }
}

// ---------- death (1B89) -----------------------------------------------------------------------------
function bloodPalette(f) { for (let i = 0xaa; i <= 0xb3; i++) setRGB(i, 63 - (0xaa - i) - 2 * f, 0, 0); }   // 0600
